let followupMappingState={};
function canonicalLanguageClient(value){const x=String(value||"").toLowerCase();const map={english:["english","en","en_us","en_gb"],italiano:["italian","italiano","it","it_it"],"français":["french","français","francais","fr","fr_fr"],"español":["spanish","español","es","es_es"],română:["romanian","română","ro","ro_ro"],deutsch:["german","deutsch","de","de_de"],русский:["russian","русский","ru","ru_ru"],türkçe:["turkish","türkçe","tr","tr_tr"],polski:["polish","polski","pl","pl_pl"],português:["portuguese","português","pt","pt_pt","pt_br"],ελληνικά:["greek","ελληνικά","el","el_gr"],bosnian:["bosnian","bs","bs_ba"],bulgarian:["bulgarian","bg","bg_bg"]};for(const[k,v]of Object.entries(map))if(v.includes(x))return k;return x}
function renderFollowupMapping(approved, settings){
  const leadLangs=[...new Set((window.__leadCache||[]).map(l=>canonicalLanguageClient(l.language)).filter(Boolean))];
  const templateLangs=approved.map(t=>canonicalLanguageClient(t.language)).filter(Boolean);
  const langs=[...new Set([...leadLangs,...templateLangs])].sort();
  followupMappingState=settings.followupTemplateMap||{};
  const optionsByLang={};
  for(const lang of langs){const ts=approved.filter(t=>canonicalLanguageClient(t.language)===lang);optionsByLang[lang]=ts.map(t=>({name:t.name,label:`${t.name} · ${t.language}`}));}
  const wrap=document.getElementById("followupTemplateMap");
  if(!wrap){return;}
  wrap.innerHTML=langs.length?langs.map(lang=>{const row=followupMappingState[lang]||{};const opts=optionsByLang[lang]||[];const optionHtml=(selected)=>'<option value="">— Not mapped —</option>'+opts.map(o=>`<option value="${esc(o.name)}" ${String(selected||"")===String(o.name)?"selected":""}>${esc(o.label)}</option>`).join("");return `<div class="mapping-row"><div class="mapping-language"><b>${esc(lang)}</b><span>${opts.length} approved template${opts.length===1?"":"s"}</span></div><div class="field"><label>Follow-up 1</label><select data-fu-map="${esc(lang)}" data-action="followup1">${optionHtml(row.followup1)}</select></div><div class="field"><label>Follow-up 2</label><select data-fu-map="${esc(lang)}" data-action="followup2">${optionHtml(row.followup2)}</select></div></div>`}).join(""):'<div class="empty">No lead/template languages found yet. Sync templates and import leads first.</div>';
}
function collectFollowupMapping(){const map={};document.querySelectorAll('[data-fu-map]').forEach(el=>{const lang=el.dataset.fuMap,action=el.dataset.action;map[lang]=map[lang]||{};map[lang][action]=el.value||""});return map}
async function loadSettings(){try{const c=await api("/api/config"),s=await api("/api/settings/followups");document.getElementById("settingsPhone").textContent=c.displayPhoneNumber||c.phoneNumberId||"Not configured";document.getElementById("settingsWaba").textContent=c.wabaId||"Not configured";document.getElementById("settingsVersion").textContent=c.graphApiVersion||"—";document.getElementById("settingsStatus").textContent=c.whatsappStatus|| (c.configured?"Connected":"Incomplete");document.getElementById("webhookUrl").value=location.origin+"/webhook";document.getElementById("fu1Days").value=s.data.followup1Days;document.getElementById("fu2Days").value=s.data.followup2Days;const allLeads=await api("/api/leads?limit=500");window.__leadCache=allLeads.data||[];const t=await api("/api/templates");const approved=(t.data||[]).filter(x=>String(x.status).toUpperCase()==="APPROVED");renderFollowupMapping(approved,s.data);}catch(e){toast(e.message,true)}}
async function saveFollowupSettings(){try{const r=await api("/api/settings/followups",{method:"POST",body:JSON.stringify({followup1Days:document.getElementById("fu1Days").value,followup2Days:document.getElementById("fu2Days").value,followupTemplateMap:collectFollowupMapping()})});toast(`Sequence and language mappings saved: +${r.data.followup1Days}d / +${r.data.followup2Days}d`);await loadSettings()}catch(e){toast(e.message,true)}}
async function loadNumbers(){
  try{
    const [d,c]=await Promise.all([api("/api/numbers"),api("/api/config")]);
    const configured=Boolean(c.configured);
    const status=String(c.whatsappStatus||"").toUpperCase();
    const liveNumber=c.displayPhoneNumber||c.connectedNumber||d.active||d.data?.[0]?.number||"";
    const ok=configured && status==="CONNECTED";
    const label=ok ? `${liveNumber} · Connected` : (liveNumber ? `${liveNumber} · ${status||"Not connected"}` : "Number not configured");
    document.getElementById("connectedNumber").textContent=label;
    const dot=document.querySelector("#numberPicker .number-btn");
    if(dot){dot.classList.toggle("number-online",ok);dot.classList.toggle("number-offline",!ok);}
    document.getElementById("numberMenuList").innerHTML=`<div class="number-health">
      <div><b>${esc(c.verifiedName||"Royal Hair WhatsApp")}</b><span>${esc(liveNumber||"No number")}</span></div>
      <span class="badge ${ok?"badge-green":"badge-red"}">${esc(status||"NOT CONFIGURED")}</span>
    </div>
    <div class="number-details">Phone ID: ${esc(c.phoneNumberId||"—")}<br>WABA: ${esc(c.wabaId||"—")}<br>Platform: ${esc(c.platformType||"—")}</div>
    ${(d.data||[]).map(n=>`<button onclick="selectNumber('${esc(n.number)}')">🟢 ${esc(n.number)}<br><span class="hint">${esc(n.label)}</span></button>`).join("")||`<div class="hint" style="padding:10px">No additional numbers configured.</div>`}`;
  }catch(e){document.getElementById("connectedNumber").textContent="Number status unavailable";}
}
