let contactLabels=[];
async function initBroadcastComposer(){
  try{
    const l=(await api("/api/contacts/labels")).data||[]; contactLabels=l;
    const labelOptions=l.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} (${x.count})</option>`).join("");
    const stageOptions=STAGES.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("");
    document.getElementById("broadcastAudienceValue").innerHTML=labelOptions||stageOptions;
    document.getElementById("broadcastLanguage").innerHTML=`<option value="">All languages</option>`+Object.values(BITRIX_LANGUAGE_NAMES).map(x=>`<option>${esc(x)}</option>`).join("");
    document.getElementById("broadcastTemplate").innerHTML=templateOptionHtml();
    renderBroadcastAudience();
  }catch(e){}
}
function getBroadcastSelectedValues(){
  const sel=document.getElementById("broadcastAudienceValue");
  return Array.from(sel?.selectedOptions||[]).map(o=>o.value).filter(Boolean);
}
function renderBroadcastAudience(){
  const mode=document.getElementById("broadcastAudience").value, sel=document.getElementById("broadcastAudienceValue"), hint=document.getElementById("broadcastAudienceHint");
  if(mode==="label"){
    sel.multiple=true; sel.size=Math.min(7,Math.max(3,contactLabels.length||3));
    sel.innerHTML=contactLabels.map(x=>`<option value="${esc(x.name)}">${esc(x.name)} (${x.count})</option>`).join("")||`<option value="" disabled>No labels</option>`;
    if(hint)hint.textContent="Hold Ctrl (Windows) or Cmd (Mac) to select multiple CSV labels.";
  }else{
    sel.multiple=false; sel.size=1;
    sel.innerHTML=STAGES.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join("");
    if(hint)hint.textContent="Select one lead stage.";
  }
  renderBroadcastFields(); updateBroadcastCount();
}
function renderBroadcastFields(){const t=getSelectedTemplateFromValue(document.getElementById("broadcastTemplate")?.value);document.getElementById("broadcastFields").innerHTML=t?templateDynamicHtml(t,"audience"):"<div class='hint'>Select an approved template.</div>"}
async function updateBroadcastCount(){
  const mode=document.getElementById("broadcastAudience").value,values=getBroadcastSelectedValues(),language=document.getElementById("broadcastLanguage").value;
  let count=0;
  if(mode==="label"){
    const wanted=new Set(values);
    count=new Set(contacts.filter(c=>(c.labels||[]).some(l=>wanted.has(l))&&(!language||String(c.language||"").toLowerCase()===language.toLowerCase())).map(c=>c.phone||c.wa_id)).size;
  }else{
    const value=values[0]||"";
    count=leads.filter(l=>l.stage===value&&(!language||String(l.language||"").toLowerCase()===language.toLowerCase())).length;
  }
  document.getElementById("broadcastAudienceCount").textContent=`${count} eligible contacts/leads`;
}
async function sendAudienceBroadcast(){
  const mode=document.getElementById("broadcastAudience").value,values=getBroadcastSelectedValues(),language=document.getElementById("broadcastLanguage").value,t=getSelectedTemplateFromValue(document.getElementById("broadcastTemplate").value);
  if(!values.length||!t)return toast("Select an audience and approved template");
  try{
    const x=collectSenderData(t,"audience"),media=await ensureTemplateConfig(t,"audience");
    if(mode==="label"){
      const wanted=new Set(values);
      const seen=new Set();
      const audience=contacts.filter(c=>{
        const phone=c.phone||c.wa_id||"";
        if(!phone||seen.has(phone)||!(c.labels||[]).some(l=>wanted.has(l)))return false;
        if(language&&String(c.language||"").toLowerCase()!==language.toLowerCase())return false;
        seen.add(phone);return true;
      });
      if(!audience.length)return toast("No eligible contacts");
      const r=await api("/api/campaigns",{method:"POST",body:JSON.stringify({name:`Labels · ${values.join(", ")}`,labels:values,contactIds:audience.map(c=>c.id),templateName:t.name,language:t.language,action:"broadcast",delayMs:900,variablesByLead:Object.fromEntries(audience.map(c=>[c.id,c.variables||x.variables])),mediaUrl:media,buttonPayloads:x.buttonPayloads})});
      toast(`Broadcast started for ${r.total} contacts`);
    }else{
      const value=values[0];
      const audience=leads.filter(l=>l.stage===value&&(!language||String(l.language||"").toLowerCase()===language.toLowerCase()));
      if(!audience.length)return toast("No eligible leads");
      const action=audience.some(l=>!l.contactedAt)?"initial":(audience.some(l=>!l.followup1SentAt)?"followup1":(audience.some(l=>!l.followup2SentAt)?"followup2":"final"));
      const r=await api("/api/campaigns",{method:"POST",body:JSON.stringify({name:`Stage · ${value}`,leadIds:audience.map(l=>l.id),templateName:t.name,language:t.language,action,autoLanguage:true,delayMs:900,variablesByLead:Object.fromEntries(audience.map(l=>[l.id,l.variables||x.variables])),mediaUrl:media,buttonPayloads:x.buttonPayloads})});
      toast(`Broadcast started for ${r.total} leads`);
    }
    showSection("broadcast");
  }catch(e){toast(e.message,true)}
}
