async function loadAnalytics(){try{const d=await api(`/api/analytics?days=${document.getElementById("analyticsDays")?.value||30}`);analyticsData=d.data;const t=analyticsData.totals;document.getElementById("analyticsKpis").innerHTML=[[`Leads`,t.leads,"Total pipeline"],[`Response rate`,`${t.responseRate}%`,"Inbound activity / contacted"],[`Photo rate`,`${t.photoRate}%`,"Contacted leads reaching photos"],[`Avg response`,humanMinutes(t.avgResponseMinutes),"Inbound → agent reply"]].map(x=>`<div class="intel-kpi"><small>${x[0]}</small><strong>${x[1]}</strong><span>${x[2]}</span></div>`).join("");const days=Object.entries(analyticsData.byDay||{}).slice(-31);const max=Math.max(1,...days.map(([_,x])=>Math.max(x.sent,x.received)));document.getElementById("messageChart").innerHTML=days.length?days.map(([day,x])=>`<div class="mini-bar-wrap" title="${day}: ${x.received} inbound / ${x.sent} outbound"><div style="display:flex;align-items:flex-end;gap:2px;height:100%"><i class="mini-bar" style="height:${Math.max(3,x.received/max*100)}%;flex:1;opacity:.8"></i><i class="mini-bar" style="height:${Math.max(3,x.sent/max*100)}%;flex:1;opacity:.35"></i></div><div class="mini-label">${day.slice(5)}</div></div>`).join(""):"<div class='empty'>No activity in this period.</div>";const langs=Object.entries(analyticsData.language||{}).sort((a,b)=>b[1]-a[1]);const lt=Math.max(1,...langs.map(x=>x[1]));document.getElementById("languageChart").innerHTML=langs.map(([l,n])=>`<div class="lang-row"><span>${esc(l)}</span><div class="lang-track"><i style="width:${n/lt*100}%"></i></div><b>${n}</b></div>`).join("")||`<div class='empty'>No language data yet.</div>`;const st=Object.entries(analyticsData.stage||{});const total=Math.max(1,t.leads);document.getElementById("analyticsStages").innerHTML=st.map(([x,n])=>`<div class="funnel-row"><span>${esc(x)}</span><div class="funnel-bar"><i style="width:${n/total*100}%;background:${STAGE_COLORS[x]||'#1769aa'}"></i></div><b>${n}</b></div>`).join("")}catch(e){toast(e.message,true)}}
