async function runAiAssist(){if(!aiSelectedLeadId)return toast("Select a lead first");const el=document.getElementById("aiResult");el.innerHTML=`<div class="empty">Analyzing conversation…</div>`;try{const d=await api("/api/ai/assist",{method:"POST",body:JSON.stringify({leadId:aiSelectedLeadId,task:document.getElementById("aiTask").value,instruction:document.getElementById("aiInstruction").value})});const x=d.data;el.innerHTML=`<div class="ai-result"><div class="ai-box full"><h4>Summary · ${d.aiEnabled?'AI':'Smart fallback'}</h4><p>${esc(x.summary||'—')}</p></div><div class="ai-box"><h4>Intent</h4><p>${esc(x.intent||'—')}</p></div><div class="ai-box"><h4>Next action</h4><p>${esc(x.nextAction||'—')}</p></div><div class="ai-box"><h4>Risks / escalation</h4><p>${esc(Array.isArray(x.risks)?x.risks.join('\n'):x.risks||'None detected')}</p></div><div class="ai-box full"><h4>Suggested reply · ${esc(d.language||'—')}</h4><p>${esc(x.suggestedReply||'—')}</p><div class="actions" style="margin-top:10px"><button class="btn btn-primary btn-sm" onclick="copyAiReply()">Copy reply</button><button class="btn btn-light btn-sm" onclick="useAiReply()">Open in Inbox</button></div></div></div>`;window._aiReply=x.suggestedReply||''}catch(e){el.innerHTML=`<div class="empty danger-text">${esc(e.message)}</div>`}}
