async function useAiReply(){const l=leads.find(x=>x.id===aiSelectedLeadId);if(!l)return;showSection("inbox");await new Promise(r=>setTimeout(r,150));await openConversation(l.phone);const box=document.getElementById("chatText");if(box){box.value=window._aiReply||"";box.focus();toast("Suggested reply loaded into the composer")}}
async function loadTeam(){try{teamData=await api("/api/team");const agents=teamData.agents||[];document.getElementById("agentList").innerHTML=agents.map(a=>`<div class="agent-card"><div class="agent-avatar">${esc(a.avatar||initials(a.name))}</div><div><h4>${esc(a.name)} <span class="assignment-pill">${esc(a.role)}</span></h4><p>${esc(a.email||'No email')} · ${esc(a.status||'offline')} · ${a.assignedLeads||0} assigned leads</p></div><div class="actions"><button class="btn btn-light btn-sm" onclick="useAgent('${esc(a.id)}')">Use</button><button class="btn btn-light btn-sm" onclick="editAgent('${esc(a.id)}')">Edit</button></div></div>`).join("");document.getElementById("roleList").innerHTML=Object.entries(teamData.roles||{}).map(([role,perms])=>`<div style="padding:12px 0;border-bottom:1px solid rgba(20,70,100,.07)"><b style="font-size:10px">${esc(role)}</b><div class="permission-list">${perms.map(p=>`<span class="permission">${esc(p)}</span>`).join("")}</div></div>`).join("");document.getElementById("performanceRows").innerHTML=agents.map(a=>`<div class="perf-row"><b>${esc(a.name)}</b><span>${a.assignedLeads||0}</span><span>${a.sentMessages||0}</span><span>${a.photos||0}</span><span>${a.conversionRate||0}%</span></div>`).join("")||`<div class="empty">No agents yet.</div>`}catch(e){toast(e.message,true)}}
function openAgentModal(id=null){const a=(teamData?.agents||[]).find(x=>x.id===id);openModal(id?"Edit agent":"Add agent",`<div class="form-grid"><div class="field"><label>Name</label><input id="agentName" value="${esc(a?.name||'')}"></div><div class="field"><label>Email</label><input id="agentEmail" value="${esc(a?.email||'')}"></div><div class="field"><label>Role</label><select id="agentRole">${Object.keys(teamData?.roles||{}).map(r=>`<option ${a?.role===r?'selected':''}>${esc(r)}</option>`).join("")}</select></div><div class="field"><label>Status</label><select id="agentStatus"><option ${a?.status==='online'?'selected':''}>online</option><option ${a?.status==='offline'?'selected':''}>offline</option><option ${a?.status==='away'?'selected':''}>away</option></select></div></div><div class="actions"><button class="btn btn-primary" onclick="saveAgent('${esc(id||'')}')">Save</button>${id?`<button class="btn btn-light" onclick="deleteAgent('${esc(id)}')">Remove</button>`:''}</div>`)}
function useAgent(id){localStorage.setItem("rh_agent_id",id);toast("Agent selected for this browser");loadTeam()}
function editAgent(id){openAgentModal(id)}
async function saveAgent(id){try{const body={name:document.getElementById("agentName").value,email:document.getElementById("agentEmail").value,role:document.getElementById("agentRole").value,status:document.getElementById("agentStatus").value};await api(id?`/api/team/agents/${id}`:"/api/team/agents",{method:id?"PATCH":"POST",body:JSON.stringify(body)});closeModal();await loadTeam();toast("Agent saved") }catch(e){toast(e.message,true)}}
async function deleteAgent(id){if(!confirm("Remove this agent?"))return;try{await api(`/api/team/agents/${id}`,{method:"DELETE"});closeModal();loadTeam();toast("Agent removed")}catch(e){toast(e.message,true)}}

async function initialize(){await Promise.allSettled([loadCountries(),loadTemplates(),loadContacts(),loadLabels(),loadDashboard(),loadLeadManager(),loadNumbers(),loadSettings(),loadAnalytics(),loadTeam()]);await initBroadcastComposer();loadBitrixLeads(true);await pollIncomingNotifications();if(!window._incomingPollTimer)window._incomingPollTimer=setInterval(()=>pollIncomingNotifications(),3000);if(!window._pageRefreshTimer)window._pageRefreshTimer=setInterval(()=>{if(document.getElementById("section-bitrix").classList.contains("active"))loadBitrixLeads(false);if(document.getElementById("section-lead-manager").classList.contains("active"))loadLeadManager();if(document.getElementById("section-inbox").classList.contains("active"))loadInbox();if(document.getElementById("section-dashboard").classList.contains("active"))loadDashboard()},5000)}
initialize();
